class Solution {
  public int longestSubarray(int[] nums, int k) {
    int n = nums.length, best = 0;
    for (int l = 0; l < n; l++) {
      long sum = 0;
      java.util.HashSet<Integer> doubles = new java.util.HashSet<>();
      for (int r = l; r < n; r++) {
        sum += nums[r];
        doubles.add((int) (((2L * nums[r]) % k + k) % k));
        int rem = (int) (((sum % k) + k) % k);
        if (rem == 0 || doubles.contains(rem)) best = Math.max(best, r - l + 1);
      }
    }
    return best;
  }
}
